    "rules.section.gameplay": "Gameplay",
    "rules.section.names": "Names",
    "rules.ban.permanent": "Permanent\x20ban",
    "rules.ban.week": "1\x20week\x20ban",
    "rules.ban.day": "1\x20day\x20ban",
    "rules.again.permanent":
      "Caught\x20again\x20after\x20that:\x20permanent\x20ban",
    "rules.again.longer":
      "Caught\x20again:\x20every\x20ban\x20is\x20longer\x20than\x20the\x20last",
    "rules.offense1": "1st\x20time:",
    "rules.offense2": "2nd\x20time:",
    "rules.offense3": "3rd\x20time:",
    "rules.multibox.title": "Multiboxing",
    "rules.multibox.body":
      "Controlling\x20several\x20tanks\x20at\x20once\x20that\x20move\x20and\x20aim\x20together.\x20One\x20player\x20gets\x20the\x20power\x20of\x20a\x20whole\x20group.",
    "rules.bots.title": "Bots",
    "rules.bots.body":
      "Tanks\x20run\x20by\x20a\x20program\x20instead\x20of\x20a\x20player,\x20usually\x20to\x20farm\x20score\x20or\x20hunt\x20other\x20players.\x20Every\x20kind\x20counts,\x20including:",
    "rules.bots.farmbots.title": "Farmbots",
    "rules.bots.farmbots.body":
      "Spawn\x20in,\x20lock\x20onto\x20nearby\x20shapes\x20and\x20farm\x20until\x20they\x20are\x20strong\x20enough\x20to\x20hunt\x20someone\x20down.",
    "rules.bots.farming.title": "Automated\x20farming",
    "rules.bots.farming.body":
      "Spawning\x20low-level\x20tanks\x20just\x20to\x20kill\x20them\x20for\x20fast\x20score.",
    "rules.bots.aimbot.title": "Aimbot",
    "rules.bots.aimbot.body":
      "Locks\x20your\x20aim\x20onto\x20players.\x20Most\x20farmbots\x20use\x20one,\x20and\x20it\x20is\x20banned\x20on\x20its\x20own\x20too.",
    "rules.fov.title": "FOV\x20script",
    "rules.fov.body":
      "Seeing\x20more\x20of\x20the\x20map\x20than\x20your\x20tank\x20allows,\x20so\x20you\x20spot\x20players\x20from\x20farther\x20away\x20than\x20you\x20should.",
    "rules.flip.title": "Flipfire\x20script",
    "rules.flip.body":
      "Tanks\x20with\x20unsynced\x20barrels\x20can\x20stack\x20bullets\x20by\x20rotating.\x20That\x20is\x20an\x20allowed\x20mechanic,\x20but\x20using\x20a\x20script\x20to\x20do\x20it\x20is\x20not.",
    "rules.leader.title": "Player\x20locator",
    "rules.leader.body":
      "Shows\x20you\x20where\x20a\x20player\x20is\x20without\x20actually\x20seeing\x20them,\x20like\x20leader\x20locator\x20scripts.",
    "rules.predator.title": "Predator\x20stack\x20script",
    "rules.predator.body":
      "Automated\x20stacking\x20of\x20Predator\x20bullets.",
    "rules.macro.title": "Input\x20scripts\x20and\x20macros",
    "rules.macro.body":
      "Any\x20other\x20script\x20or\x20macro\x20that\x20presses\x20keys,\x20moves,\x20aims\x20or\x20fires\x20for\x20you.",
    "rules.allowed.title": "Allowed",
    "rules.allowed.intro":
      "Scripts\x20are\x20only\x20banned\x20if\x20they\x20give\x20you\x20an\x20unfair\x20advantage\x20or\x20ruin\x20the\x20game\x20for\x20others.\x20Scripts\x20like\x20these\x20are\x20fine:",
    "rules.allowed.themes.title": "Theme\x20scripts",
    "rules.allowed.themes.body": "Change colors, fonts and how the game looks.",
    "rules.allowed.party.title": "Party\x20scripts",
