      content:
        "\x0a\x20\x20\x20\x20\x20\x20\x20\x20<ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<h2>Shop:</h2>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>The\x20shop\x20now\x20has\x20skins:\x20buy\x20them\x20with\x20Shinies\x20and\x20wear\x20them\x20on\x20every\x20tank</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Featured\x20skins\x20go\x20on\x20sale\x20for\x20a\x20limited\x20time</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Equip\x20your\x20skins\x20and\x20pets\x20from\x20the\x20Locker</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Everyone\x20with\x20the\x2010th\x20Anniversary\x20badge\x20gets\x20the\x20exclusive\x20Ten\x20Years\x20skin</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Skins\x20and\x20pets\x20can\x20be\x20turned\x20off\x20in\x20the\x20settings,\x20or\x20shown\x20for\x20your\x20team\x20only</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<h2>Account:</h2>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>New\x20profile\x20page</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>See\x20how\x20you\x20do\x20with\x20each\x20tank:\x20kills,\x20best\x20score,\x20longest\x20life\x20and\x20more,\x20split\x20by\x20gamemode</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Show\x20off\x20on\x20your\x20profile:\x20pick\x20the\x204\x20stats\x20everyone\x20sees,\x20like\x20your\x20best\x20score\x20as\x20Overlord</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Your\x20most\x20played\x20tanks\x20up\x20front</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Your\x20total\x20hours\x20played\x20are\x20now\x20tracked</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<h2>Tank\x20Editor:</h2>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Bigger\x20packs:\x20a\x20pack\x20may\x20now\x20be\x20900\x20KB\x20and\x20hold\x20512\x20tanks,\x20up\x20from\x20256\x20KB\x20and\x20256</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>The\x20upgrade\x20grid\x20opens\x20a\x20third\x20row\x20when\x20a\x20tank\x20offers\x20more\x20than\x2010\x20upgrades</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<h2>Bug\x20Fixes:</h2>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Fixed\x20copying\x20or\x20duplicating\x20a\x20turret\x20or\x20a\x20barrel\x20leaving\x20behind\x20everything\x20mounted\x20on\x20it</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Fixed\x20copying\x20or\x20duplicating\x20a\x20group\x20mixing\x20up\x20the\x20order\x20of\x20its\x20layers</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Fixed\x20the\x20editor\x27s\x20room\x20budget\x20counting\x20traps\x20as\x20half\x20the\x20size\x20the\x20lobby\x20gives\x20them,\x20so\x20a\x20tank\x20could\x20pass\x20in\x20the\x20editor\x20and\x20be\x20refused\x20on\x20load</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<li>Fixed\x20a\x20Necromancer\x27s\x20drones\x20reshuffling\x20which\x20one\x20draws\x20on\x20top\x20every\x20time\x20a\x20drone\x20was\x20lost\x20or\x20raised</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20\x20\x20\x20\x20</ul>",
